        }
        std::vector<int > difference;
        const std::vector<int >& lhs_diff = nonzeros(this->B0 * (this->B0T * indicator(VertexOneRingset_0, M.n_vertices())));
        const std::vector<int >& rhs_diff = VertexOneRingset_1;
