function output = heartlib(M)
% output = heartlib(M)
%
%    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector from MeshConnectivity
%    Vertices, Edges, Faces from FundamentalPolygonAccessors(M)
%    M ∈ FaceMesh 
%    V, E, F = ElementSets( M )
%    `∂⁰`, `∂¹` = BoundaryMatrices(M) 
%    `∂⁰ᵀ` = `∂⁰`ᵀ
%    `B⁰`, `B¹` = UnsignedBoundaryMatrices(M)
%    `B⁰ᵀ` = `B⁰`ᵀ
%    `B¹ᵀ` = `B¹`ᵀ
%    
%    
%    VertexOneRing(v) = vertexset(NonZeros(`B⁰` (`B⁰ᵀ` IndicatorVector({v})))) - {v} where v ∈ V
%    VertexOneRing(v) = vertexset(NonZeros(`B⁰` (`B⁰ᵀ` IndicatorVector(v)))) - v where v ⊂  V
%    
%    EdgeIndex(i, j) = eset_1 where i,j ∈ V,
%    eset = edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({i}))) ∩ edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({j})))
%    
%    NeighborVerticesInFace(f, v) = tuple(vset1_1, vset2_1) where v ∈ V, f ∈ F,
%    es = edgeset(NonZeros(`∂¹` IndicatorVector({f}))),
%    nes = { s for s ∈ es if `∂⁰`_v,s != 0 },
%    eset1 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = -1},
%    vset1 = vertexset(NonZeros(`B⁰` IndicatorVector(eset1))) - {v},
%    eset2 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = 1 },
%    vset2 = vertexset(NonZeros(`B⁰` IndicatorVector(eset2))) - {v}
%    
%    NextVerticeInFace(f, v) = vset_1 where v ∈ V, f ∈ F,
%    eset = { e for e ∈ Edges(f) if `∂¹`_e,f `∂⁰`_v,e = -1},
%    vset = Vertices(eset) - {v}
%    
%    
%    OrientedVertices(f) = tuple(vs_1, i, j)    where f ∈ F,
%    vs = Vertices(f),
%    i,j = NeighborVerticesInFace(f, vs_1)
%    
%    FaceIndex(i,j,k) = fset_1  where i,j,k ∈ V,
%    ufv = `B¹ᵀ` `B⁰ᵀ`,
%    iface = faceset(NonZeros(ufv  IndicatorVector({i}))),
%    jface = faceset(NonZeros(ufv  IndicatorVector({j}))),
%    kface = faceset(NonZeros(ufv IndicatorVector({k}))),
%    fset = iface ∩ jface ∩ kface
%     
%    
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E, F] = M.ElementSets();
    function output = FundamentalPolygonAccessors(M)
    % output = FundamentalPolygonAccessors(M)
    %
    %    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector  from MeshConnectivity
    %    
    %    M ∈ FaceMesh 
    %    
    %    V, E, F = ElementSets( M )
    %    dee0, dee1 = BoundaryMatrices(M) 
    %    B0, B1 = UnsignedBoundaryMatrices(M)
    %    B0T = B0ᵀ
    %    B1T = B1ᵀ
    %    
    %    Vertices(S) = S₁ where S: CellularSet
    %    Edges(S)    = S₂ where S: CellularSet
    %    Faces(S)    = S₃ where S: CellularSet
    %     
    %    Vertices(f) = vertexset(NonZeros(B0 (B1 IndicatorVector({f})))) where f ∈ F
    %    Vertices(G) = vertexset(NonZeros(B0 (B1 IndicatorVector(G)))) where G ⊂ F
    %    Vertices(e) = vertexset(NonZeros(B0 IndicatorVector({e}))) where e ∈ E
    %    Vertices(H) = vertexset(NonZeros(B0 IndicatorVector(H))) where H ⊂ E
    %     
    %    Edges(v) = edgeset(NonZeros(B0T IndicatorVector({v}))) where v ∈ V
    %    Edges(f) = edgeset(NonZeros(B1 IndicatorVector({f}))) where f ∈ F
    %    
    %    Faces(v) = faceset(NonZeros(B1T (B0T IndicatorVector({v})))) where v ∈ V
    %    Faces(e) = faceset(NonZeros(B1T IndicatorVector({e}))) where e ∈ E
        dimv_0 = M.n_vertices();
        dime_0 = M.n_edges();
        dimf_0 = M.n_faces();
        [V, E, F] = M.ElementSets();
        [dee0, dee1] = M.BoundaryMatrices();
        [B0, B1] = M.UnsignedBoundaryMatrices();
        % B0T = B0ᵀ
        B0T = B0';
        % B1T = B1ᵀ
        B1T = B1';
        function [ret] = Vertices(S)
            ret = S(1);
        end
        function [ret_1] = Edges(S)
            ret_1 = S(2);
        end
        function [ret_2] = Faces(S)
            ret_2 = S(3);
        end
        function [ret_3] = Vertices_0(f)
            assert(numel(f) == 1);
            assert( ismember(f, F) );
            ret_3 = NonZeros(B0 * (B1 * indicator([f], M.n_faces())));
        end
        function [ret_4] = Vertices_1(G)
            ret_4 = NonZeros(B0 * (B1 * indicator(G, M.n_faces())));
        end
        function [ret_5] = Vertices_2(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            ret_5 = NonZeros(B0 * indicator([e], M.n_edges()));
        end
        function [ret_6] = Vertices_3(H)
            ret_6 = NonZeros(B0 * indicator(H, M.n_edges()));
        end
        function [ret_7] = Edges_0(v)
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            ret_7 = NonZeros(B0T * indicator([v], M.n_vertices()));
        end
        function [ret_8] = Edges_1(f)
            assert(numel(f) == 1);
            assert( ismember(f, F) );
            ret_8 = NonZeros(B1 * indicator([f], M.n_faces()));
        end
        function [ret_9] = Faces_0(v)
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            ret_9 = NonZeros(B1T * (B0T * indicator([v], M.n_vertices())));
        end
        function [ret_10] = Faces_1(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            ret_10 = NonZeros(B1T * indicator([e], M.n_edges()));
        end
        output.V = V;
        output.E = E;
        output.F = F;
        output.dee0 = dee0;
        output.dee1 = dee1;
        output.B0 = B0;
        output.B1 = B1;
        output.B0T = B0T;
        output.B1T = B1T;
        output.Vertices = @Vertices;
        output.Edges = @Edges;
        output.Faces = @Faces;
        output.Vertices_0 = @Vertices_0;
        output.Vertices_1 = @Vertices_1;
        output.Vertices_2 = @Vertices_2;
        output.Vertices_3 = @Vertices_3;
        output.Edges_0 = @Edges_0;
        output.Edges_1 = @Edges_1;
        output.Faces_0 = @Faces_0;
        output.Faces_1 = @Faces_1;
        output.M = M;
    end
    FundamentalPolygonAccessors_ = FundamentalPolygonAccessors(M);
    Vertices = @FundamentalPolygonAccessors_.Vertices;
    Vertices_0 = @FundamentalPolygonAccessors_.Vertices_0;
    Vertices_1 = @FundamentalPolygonAccessors_.Vertices_1;
    Vertices_2 = @FundamentalPolygonAccessors_.Vertices_2;
    Vertices_3 = @FundamentalPolygonAccessors_.Vertices_3;
    Edges = @FundamentalPolygonAccessors_.Edges;
    Edges_0 = @FundamentalPolygonAccessors_.Edges_0;
    Edges_1 = @FundamentalPolygonAccessors_.Edges_1;
    Faces = @FundamentalPolygonAccessors_.Faces;
    Faces_0 = @FundamentalPolygonAccessors_.Faces_0;
    Faces_1 = @FundamentalPolygonAccessors_.Faces_1;
    [dee0, dee1] = M.BoundaryMatrices();
    % `∂⁰ᵀ` = `∂⁰`ᵀ

    dee0T = dee0';
    [B0, B1] = M.UnsignedBoundaryMatrices();
    % `B⁰ᵀ` = `B⁰`ᵀ

    B0T = B0';
    % `B¹ᵀ` = `B¹`ᵀ

    B1T = B1';
    function [ret] = VertexOneRing(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret = setdiff(NonZeros(B0 * (B0T * indicator([v], M.n_vertices()))), [v]);
    end

    function [ret_1] = VertexOneRing_0(v)
        ret_1 = setdiff(NonZeros(B0 * (B0T * indicator(v, M.n_vertices()))), v);
    end

    function [ret_2] = EdgeIndex(i, j)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );

        % eset = edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({i}))) ∩ edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({j})))
        eset = intersect(NonZeros(dee0T * indicator([i], M.n_vertices())), NonZeros(dee0T * indicator([j], M.n_vertices())));
        ret_2 = eset(1);
    end

    function [ret_3, ret_4] = NeighborVerticesInFace(f, v)
        assert(numel(f) == 1);
        assert(numel(v) == 1);
        assert( ismember(v, V) );
        assert( ismember(f, F) );

        % es = edgeset(NonZeros(`∂¹` IndicatorVector({f})))
        es = NonZeros(dee1 * indicator([f], M.n_faces()));

        % nes = { s for s ∈ es if `∂⁰`_v,s != 0 }
        NeighborVerticesInFaceset_1 = [];
        range = es;
        for index = 1:length(range)
            s = range(index);
            if dee0(v, s) ~= 0
                NeighborVerticesInFaceset_1 = [NeighborVerticesInFaceset_1; s];
            end
        end
        nes = NeighborVerticesInFaceset_1;

        % eset1 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = -1}
        NeighborVerticesInFaceset_2 = [];
        range_1 = nes;
        for index_1 = 1:length(range_1)
            e = range_1(index_1);
            if dee1(e, f) * dee0(v, e) == -1
                NeighborVerticesInFaceset_2 = [NeighborVerticesInFaceset_2; e];
            end
        end
        eset1 = NeighborVerticesInFaceset_2;

        % vset1 = vertexset(NonZeros(`B⁰` IndicatorVector(eset1))) - {v}
        vset1 = setdiff(NonZeros(B0 * indicator(eset1, M.n_edges())), [v]);

        % eset2 = { e for e ∈ nes if `∂¹`_e,f `∂⁰`_v,e = 1 }
        NeighborVerticesInFaceset_4 = [];
        range_2 = nes;
        for index_2 = 1:length(range_2)
            e = range_2(index_2);
            if dee1(e, f) * dee0(v, e) == 1
                NeighborVerticesInFaceset_4 = [NeighborVerticesInFaceset_4; e];
            end
        end
        eset2 = NeighborVerticesInFaceset_4;

        % vset2 = vertexset(NonZeros(`B⁰` IndicatorVector(eset2))) - {v}
        vset2 = setdiff(NonZeros(B0 * indicator(eset2, M.n_edges())), [v]);
        tuple = [vset1(1),vset2(1)];
        ret_3 = tuple(1);
        ret_4 = tuple(2);
    end

    function [ret_5] = NextVerticeInFace(f, v)
        assert(numel(f) == 1);
        assert(numel(v) == 1);
        assert( ismember(v, V) );
        assert( ismember(f, F) );

        % eset = { e for e ∈ Edges(f) if `∂¹`_e,f `∂⁰`_v,e = -1}
        NextVerticeInFaceset_0 = [];
        range_3 = Edges_1(f);
        for index_3 = 1:length(range_3)
            e = range_3(index_3);
            if dee1(e, f) * dee0(v, e) == -1
                NextVerticeInFaceset_0 = [NextVerticeInFaceset_0; e];
            end
        end
        eset = NextVerticeInFaceset_0;

        % vset = Vertices(eset) - {v}
        vset = setdiff(Vertices_3(eset), [v]);
        ret_5 = vset(1);
    end

    function [ret_6, ret_7, ret_8] = OrientedVertices(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        % vs = Vertices(f)
        vs = Vertices_0(f);

        [i, j] = NeighborVerticesInFace(f, vs(1));
        tuple_1 = [vs(1),i,j];
        ret_6 = tuple_1(1);
        ret_7 = tuple_1(2);
        ret_8 = tuple_1(3);
    end

    function [ret_9] = FaceIndex(i, j, k)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert(numel(k) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );
        assert( ismember(k, V) );

        % ufv = `B¹ᵀ` `B⁰ᵀ`
        ufv = B1T * B0T;

        % iface = faceset(NonZeros(ufv  IndicatorVector({i})))
        iface = NonZeros(ufv * indicator([i], M.n_vertices()));

        % jface = faceset(NonZeros(ufv  IndicatorVector({j})))
        jface = NonZeros(ufv * indicator([j], M.n_vertices()));

        % kface = faceset(NonZeros(ufv IndicatorVector({k})))
        kface = NonZeros(ufv * indicator([k], M.n_vertices()));

        % fset = iface ∩ jface ∩ kface
        fset = intersect(iface, intersect(jface, kface));
        ret_9 = fset(1);
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.dee0 = dee0;
    output.dee1 = dee1;
    output.dee0T = dee0T;
    output.B0 = B0;
    output.B1 = B1;
    output.B0T = B0T;
    output.B1T = B1T;
    output.VertexOneRing = @VertexOneRing;
    output.VertexOneRing_0 = @VertexOneRing_0;
    output.EdgeIndex = @EdgeIndex;
    output.NeighborVerticesInFace = @NeighborVerticesInFace;
    output.NextVerticeInFace = @NextVerticeInFace;
    output.OrientedVertices = @OrientedVertices;
    output.FaceIndex = @FaceIndex;
    output.M = M;
end

